TEMPLATE = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Travel Registration — {{AGENCY_NAME}}</title>\n  <style>\n    :root {\n      --brand: #17a39b; --brand-dark: #128a81; --brand-light: #e6f7f6;\n      --ink: #111827; --muted: #6b7280; --border: #e5e7eb;\n      --bg: #f9fafb; --white: #fff;\n      --red: #dc2626;\n    }\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n      background: var(--bg); color: var(--ink); min-height: 100vh;\n    }\n\n    /* ── Header ── */\n    .page-header {\n      background: var(--brand);\n      padding: 1.5rem 1.5rem 2.5rem;\n      text-align: center;\n    }\n    .agency-logo {\n      height: 56px; max-width: 180px; object-fit: contain;\n      display: block; margin: 0 auto .9rem;\n      border-radius: 8px;\n    }\n    .page-header h1 { color:#fff; font-size:1.35rem; font-weight:700; line-height:1.3; }\n    .page-header .subtitle { color:rgba(255,255,255,.82); font-size:.88rem; margin-top:.35rem; }\n\n    /* ── Page wrapper ── */\n    .page { max-width:700px; margin:-1.5rem auto 3rem; padding:0 1rem; }\n\n    /* ── Card shell ── */\n    .card {\n      background:var(--white); border:1px solid var(--border);\n      border-radius:16px; margin-bottom:1.25rem;\n      box-shadow:0 2px 8px rgba(0,0,0,.06); overflow:hidden;\n    }\n\n    /* ── Itinerary toggle header ── */\n    .itin-toggle {\n      width:100%; background:none; border:none; cursor:pointer;\n      padding:1.1rem 1.4rem;\n      display:flex; align-items:center; justify-content:space-between;\n      text-align:left;\n    }\n    .itin-toggle:hover { background:var(--bg); }\n    .itin-toggle-left h2 { font-size:.95rem; font-weight:700; }\n    .itin-toggle-left .itin-meta { font-size:.8rem; color:var(--muted); margin-top:.2rem; }\n    .itin-chevron {\n      width:20px; height:20px; flex-shrink:0; color:var(--muted);\n      transition:transform .22s;\n    }\n    .itin-chevron.open { transform:rotate(180deg); }\n    .itin-body { display:none; border-top:1px solid var(--border); }\n    .itin-body.open { display:block; }\n\n    /* ── Timeline ── */\n    .timeline { padding:.5rem 1.2rem 1.2rem; }\n    .tl-item {\n      display:flex; gap:.9rem; padding:.65rem 0;\n      position:relative;\n    }\n    /* vertical line between items */\n    .tl-item:not(:last-child)::after {\n      content:\'\'; position:absolute;\n      left:calc(.9rem + 16px); top:40px;\n      width:2px; bottom:-6px;\n      background:var(--border);\n    }\n\n    /* date badge */\n    .tl-date {\n      flex-shrink:0; width:34px; text-align:center;\n      padding:.3rem .1rem; border-radius:8px;\n      font-size:.65rem; font-weight:700; line-height:1.2;\n      text-transform:uppercase; min-height:36px;\n      display:flex; flex-direction:column; align-items:center; justify-content:center;\n    }\n    .tl-date.accent { background:var(--brand); color:#fff; }\n    .tl-date.dark   { background:#1f2937;      color:#fff; }\n    .tl-date.empty  { background:transparent;  }\n\n    /* content */\n    .tl-content { flex:1; min-width:0; }\n    .tl-top { display:flex; align-items:center; gap:.45rem; flex-wrap:wrap; margin-bottom:.2rem; }\n    .tl-chip {\n      font-size:.62rem; font-weight:700; text-transform:uppercase;\n      letter-spacing:.04em; padding:.18rem .5rem; border-radius:4px;\n    }\n    .chip-flight   { background:#dbeafe; color:#1d4ed8; }\n    .chip-hotel    { background:#fef3c7; color:#92400e; }\n    .chip-transfer { background:#d1fae5; color:#065f46; }\n    .chip-activity { background:#ede9fe; color:#5b21b6; }\n    .chip-nights   { background:#fce7f3; color:#9d174d; }\n\n    .tl-title { font-size:.9rem; font-weight:600; }\n    .tl-detail { font-size:.78rem; color:var(--muted); margin-top:.15rem; line-height:1.5; }\n    .tl-stars { color:#f59e0b; font-size:.8rem; }\n\n    /* ── Form section ── */\n    .pax-block { border-bottom:1px solid var(--border); padding:1.2rem 1.4rem; }\n    .pax-block:last-of-type { border-bottom:none; }\n    .pax-label {\n      font-size:.72rem; font-weight:700; text-transform:uppercase;\n      letter-spacing:.06em; color:var(--brand); margin-bottom:.85rem;\n    }\n    .shared-section { padding:1.2rem 1.4rem; border-top:2px solid var(--brand-light); }\n    .shared-title {\n      font-size:.72rem; font-weight:700; text-transform:uppercase;\n      letter-spacing:.06em; color:var(--muted); margin-bottom:.9rem;\n    }\n\n    /* fields */\n    .field { display:flex; flex-direction:column; gap:.28rem; margin-bottom:.7rem; }\n    .field:last-child { margin-bottom:0; }\n    label.fl { font-size:.78rem; font-weight:600; }\n    label.fl .req { color:var(--red); }\n    input[type=text],input[type=email],input[type=tel],input[type=date] {\n      width:100%; padding:.58rem .8rem;\n      border:1.5px solid var(--border); border-radius:8px;\n      font-size:.9rem; color:var(--ink); background:var(--white);\n      outline:none; transition:border-color .15s; -webkit-appearance:none;\n    }\n    input:focus { border-color:var(--brand); }\n    input.err   { border-color:var(--red); }\n    .ferr { font-size:.74rem; color:var(--red); display:none; }\n    .ferr.show { display:block; }\n\n    .row2 { display:grid; grid-template-columns:1fr 90px; gap:.5rem; }\n    .row2b{ display:grid; grid-template-columns:110px 1fr; gap:.5rem; }\n\n    /* submit */\n    .submit-wrap { padding:1.2rem 1.4rem; border-top:1px solid var(--border); background:var(--bg); }\n    .btn-submit {\n      width:100%; background:var(--brand); color:#fff;\n      border:none; border-radius:10px; padding:.82rem 1.5rem;\n      font-size:1rem; font-weight:700; cursor:pointer; transition:background .15s;\n    }\n    .btn-submit:hover { background:var(--brand-dark); }\n    .btn-submit:disabled { opacity:.6; cursor:not-allowed; }\n    .submit-note { text-align:center; font-size:.76rem; color:var(--muted); margin-top:.55rem; }\n\n    .err-banner {\n      background:#fef2f2; border:1px solid #fca5a5; color:var(--red);\n      border-radius:8px; padding:.65rem 1rem; font-size:.86rem;\n      margin-bottom:1rem; display:none;\n    }\n    .err-banner.show { display:block; }\n\n    @media(max-width:480px){\n      .row2,.row2b { grid-template-columns:1fr; }\n    }\n  </style>\n</head>\n<body>\n\n<div class="page-header">\n  {{LOGO_HTML}}\n  <h1>{{PKG_TITLE}}</h1>\n  <div class="subtitle" id="hdr-sub">{{AGENCY_NAME}}</div>\n</div>\n\n<div class="page">\n\n  <!-- Itinerary summary -->\n  <div class="card" id="itin-card" style="display:none">\n    <button class="itin-toggle" type="button" onclick="toggleItin()">\n      <div class="itin-toggle-left">\n        <h2>🗺️ Tour Overview</h2>\n        <div class="itin-meta" id="itin-meta"></div>\n      </div>\n      <svg class="itin-chevron" id="itin-chevron" viewBox="0 0 20 20" fill="none"\n           stroke="currentColor" stroke-width="2">\n        <polyline points="5,8 10,13 15,8"/>\n      </svg>\n    </button>\n    <div class="itin-body" id="itin-body">\n      <div class="timeline" id="timeline"></div>\n    </div>\n  </div>\n\n  <div class="err-banner" id="err-banner"></div>\n\n  <!-- Registration form -->\n  <form class="card" id="reg-form" method="post"\n        action="/register/{{AGENT_ID}}/{{PACKAGE_ID}}" novalidate>\n\n    <div id="pax-sections"></div>\n\n    <div class="shared-section">\n      <div class="shared-title">Contact &amp; Address</div>\n\n      <div class="field">\n        <label class="fl" for="f-email">E-mail <span class="req">*</span></label>\n        <input type="email" id="f-email" name="email" autocomplete="email" required>\n        <span class="ferr" id="e-email">Please enter a valid email address.</span>\n      </div>\n      <div class="field">\n        <label class="fl" for="f-phone">Phone <span class="req">*</span></label>\n        <input type="tel" id="f-phone" name="phone" autocomplete="tel" required>\n        <span class="ferr" id="e-phone">Please enter a phone number.</span>\n      </div>\n      <div class="field">\n        <label class="fl">Street &amp; house number <span class="req">*</span></label>\n        <div class="row2">\n          <input type="text" id="f-street" name="street" placeholder="Street name" required>\n          <input type="text" id="f-house"  name="house_number" placeholder="No.">\n        </div>\n        <span class="ferr" id="e-street">Please enter a street.</span>\n      </div>\n      <div class="field">\n        <label class="fl">Postal code &amp; city <span class="req">*</span></label>\n        <div class="row2b">\n          <input type="text" id="f-postal" name="postal_code" placeholder="Postal code" required>\n          <input type="text" id="f-city"   name="city" placeholder="City" required>\n        </div>\n        <span class="ferr" id="e-city">Please enter postal code and city.</span>\n      </div>\n      <div class="field">\n        <label class="fl" for="f-country">Country of residence <span class="req">*</span></label>\n        <input type="text" id="f-country" name="country_of_residence"\n               placeholder="e.g. Germany" autocomplete="country-name" required>\n        <span class="ferr" id="e-country">Please enter your country.</span>\n      </div>\n      <div class="field">\n        <label class="fl" for="f-nat">Nationality <span class="req">*</span></label>\n        <input type="text" id="f-nat" name="nationality"\n               placeholder="e.g. German" required>\n        <span class="ferr" id="e-nat">Please enter your nationality.</span>\n      </div>\n    </div>\n\n    <input type="hidden" name="passengers_json" id="passengers-json">\n\n    <div class="submit-wrap">\n      <button type="submit" class="btn-submit" id="submit-btn">\n        ✈️ Secure your trip now\n      </button>\n      <div class="submit-note">\n        By submitting you confirm that all details are accurate.\n        Your data will only be used for this travel booking.\n      </div>\n    </div>\n  </form>\n</div>\n\n<script>\n  const NUM_ADULTS   = parseInt("{{NUM_ADULTS}}", 10)  || 2;\n  const NUM_CHILDREN = parseInt("{{NUM_CHILDREN}}", 10)|| 0;\n  const PRICE_STR    = "{{PRICE_STR}}";\n  const ITIN = (function(){\n    try{ return JSON.parse(\'{{ITINERARY_JSON}}\'); } catch(e){ return null; }\n  })();\n\n  /* header subtitle */\n  if (PRICE_STR) {\n    document.getElementById(\'hdr-sub\').textContent =\n      "{{AGENCY_NAME}} · " + PRICE_STR;\n  }\n\n  /* ── Passenger sections ── */\n  (function(){\n    const el = document.getElementById(\'pax-sections\');\n    let html = \'\';\n    for(let i=0;i<NUM_ADULTS;i++)   html += paxBlock(\'adult\',i+1,i);\n    for(let i=0;i<NUM_CHILDREN;i++) html += paxBlock(\'child\',i+1,NUM_ADULTS+i);\n    el.innerHTML = html;\n  })();\n\n  function paxBlock(type, num, idx){\n    const label = type===\'adult\' ? \'Adult \'+num : \'Child \'+num;\n    return `\n      <div class="pax-block" data-type="${type}" data-idx="${idx}">\n        <div class="pax-label">${label}</div>\n        <div class="field">\n          <label class="fl" for="pn${idx}">Full name (as on passport) <span class="req">*</span></label>\n          <input type="text" id="pn${idx}" class="pax-name" data-idx="${idx}"\n                 placeholder="First name Last name" required>\n          <span class="ferr" id="en${idx}">Please enter the full name.</span>\n        </div>\n        <div class="field">\n          <label class="fl" for="pd${idx}">Date of birth <span class="req">*</span></label>\n          <input type="date" id="pd${idx}" class="pax-dob" data-idx="${idx}" required>\n          <span class="ferr" id="ed${idx}">Please enter date of birth.</span>\n        </div>\n      </div>`;\n  }\n\n  /* ── Itinerary timeline ── */\n  (function(){\n    if(!ITIN) return;\n    const rows = [];\n\n    /* flights */\n    (ITIN.flights||[]).forEach(f=>{\n      const route = [f.origin, f.dest].filter(Boolean).join(\' → \') || \'Flight\';\n      const parts = [];\n      if(f.dep_time) parts.push(f.dep_time + (f.arr_time?\' → \'+f.arr_time:\'\'));\n      if(f.duration) parts.push(f.duration);\n      if(f.baggage)  parts.push(\'🧳 \'+f.baggage);\n      rows.push({chip:\'flight\', chipLabel:\'Flight\', title: route, detail: parts.join(\' · \')});\n    });\n\n    /* hotels */\n    (ITIN.hotels||[]).forEach(h=>{\n      const stars = h.stars ? \'★\'.repeat(Math.min(h.stars,5)) : \'\';\n      const parts = [];\n      if(h.nights) parts.push(h.nights+\' night\'+(h.nights>1?\'s\':\'\'));\n      if(h.board)  parts.push(h.board);\n      rows.push({chip:\'hotel\', chipLabel: (h.nights?h.nights+\' nights\':\'Hotel\'),\n                 title: h.name, stars: stars, detail: parts.join(\' · \')});\n    });\n\n    /* transfers */\n    (ITIN.transfers||[]).forEach(t=>{\n      rows.push({chip:\'transfer\', chipLabel:\'Transfer\', title: t, detail:\'\'});\n    });\n\n    /* activities */\n    (ITIN.activities||[]).forEach(a=>{\n      rows.push({chip:\'activity\', chipLabel:\'Included\', title: a, detail:\'\'});\n    });\n\n    if(!rows.length) return;\n\n    /* meta line */\n    const metaParts = [];\n    const fc = (ITIN.flights||[]).length;\n    const hc = (ITIN.hotels||[]).length;\n    if(fc) metaParts.push(fc+\' flight\'+(fc>1?\'s\':\'\'));\n    if(hc) metaParts.push(hc+\' hotel\'+(hc>1?\'s\':\'\'));\n    if(ITIN.days) metaParts.push(ITIN.days+\' days\');\n    document.getElementById(\'itin-meta\').textContent =\n      metaParts.join(\' · \') || \'Click to expand\';\n\n    const tl = document.getElementById(\'timeline\');\n    tl.innerHTML = rows.map((r,i)=>{\n      const chipClass = \'chip-\'+r.chip;\n      const dateClass = i%2===0 ? \'accent\' : \'dark\';\n      return `\n        <div class="tl-item">\n          <div class="tl-date ${dateClass}"></div>\n          <div class="tl-content">\n            <div class="tl-top">\n              <span class="tl-chip ${chipClass}">${esc(r.chipLabel)}</span>\n              <span class="tl-title">${esc(r.title)}</span>\n            </div>\n            ${r.stars?`<div class="tl-stars">${r.stars}</div>`:\'\'}\n            ${r.detail?`<div class="tl-detail">${esc(r.detail)}</div>`:\'\'}\n          </div>\n        </div>`;\n    }).join(\'\');\n\n    document.getElementById(\'itin-card\').style.display = \'block\';\n  })();\n\n  function toggleItin(){\n    const body = document.getElementById(\'itin-body\');\n    const chev = document.getElementById(\'itin-chevron\');\n    const open = body.classList.toggle(\'open\');\n    chev.classList.toggle(\'open\', open);\n  }\n\n  /* ── Validation & submit ── */\n  function clearErrs(){\n    document.querySelectorAll(\'.ferr\').forEach(e=>e.classList.remove(\'show\'));\n    document.querySelectorAll(\'input.err\').forEach(e=>e.classList.remove(\'err\'));\n    document.getElementById(\'err-banner\').classList.remove(\'show\');\n  }\n  function markErr(inputId, errId){\n    const i=document.getElementById(inputId);\n    const e=document.getElementById(errId);\n    if(i) i.classList.add(\'err\');\n    if(e) e.classList.add(\'show\');\n  }\n\n  document.getElementById(\'reg-form\').addEventListener(\'submit\', function(ev){\n    ev.preventDefault();\n    clearErrs();\n    let ok=true;\n\n    document.querySelectorAll(\'.pax-name\').forEach(inp=>{\n      const idx=inp.dataset.idx;\n      if(!inp.value.trim()){ markErr(\'pn\'+idx,\'en\'+idx); ok=false; }\n    });\n    document.querySelectorAll(\'.pax-dob\').forEach(inp=>{\n      const idx=inp.dataset.idx;\n      if(!inp.value){ markErr(\'pd\'+idx,\'ed\'+idx); ok=false; }\n    });\n\n    const email=document.getElementById(\'f-email\');\n    if(!email.value.trim()||!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email.value)){\n      markErr(\'f-email\',\'e-email\'); ok=false;\n    }\n    if(!document.getElementById(\'f-phone\').value.trim()){ markErr(\'f-phone\',\'e-phone\'); ok=false; }\n    if(!document.getElementById(\'f-street\').value.trim()){ markErr(\'f-street\',\'e-street\'); ok=false; }\n    if(!document.getElementById(\'f-postal\').value.trim()||\n       !document.getElementById(\'f-city\').value.trim()){ markErr(\'f-postal\',\'e-city\'); ok=false; }\n    if(!document.getElementById(\'f-country\').value.trim()){ markErr(\'f-country\',\'e-country\'); ok=false; }\n    if(!document.getElementById(\'f-nat\').value.trim()){ markErr(\'f-nat\',\'e-nat\'); ok=false; }\n\n    if(!ok){\n      const b=document.getElementById(\'err-banner\');\n      b.textContent=\'Please fill in all required fields.\';\n      b.classList.add(\'show\');\n      window.scrollTo({top:0,behavior:\'smooth\'});\n      return;\n    }\n\n    const passengers=[];\n    document.querySelectorAll(\'.pax-block\').forEach(block=>{\n      const idx=block.dataset.idx;\n      passengers.push({\n        type: block.dataset.type,\n        full_name: document.getElementById(\'pn\'+idx).value.trim(),\n        dob: document.getElementById(\'pd\'+idx).value,\n      });\n    });\n    document.getElementById(\'passengers-json\').value=JSON.stringify(passengers);\n\n    const btn=document.getElementById(\'submit-btn\');\n    btn.disabled=true; btn.textContent=\'Sending…\';\n    this.submit();\n  });\n\n  function esc(s){\n    return String(s||\'\').replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\');\n  }\n</script>\n</body>\n</html>\n'
